#!/usr/bin/env bash
# Light engine check: recomputes block and sky light of every chunk of a world generated by the REAL vanilla server (whose eight
# neighbours are stored too) and compares it with the light vanilla stored in the region files.
# Usage: tools/light_check.sh [server dir containing the world]   (default: the world generated by tools/world_compare.sh)
# The world comes from the vanilla server, which requires accepting the Mojang EULA: run
#   MC_EULA_ACCEPTED=true tools/world_compare.sh
# once to generate one, or pass the directory of any Java world (level-name=world).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
DIR="${1:-$ROOT/reference/world-compare/gen}"
[ -d "$DIR/world/region" ] || { echo "No world in $DIR. Run: MC_EULA_ACCEPTED=true tools/world_compare.sh" >&2; exit 2; }
cargo build -q --release -p mc-server
"$ROOT/target/release/mc-server" --check-light --dir "$DIR" 2>&1 | grep -v "INFO\|WARN"
